  or coalesce(v->>'state' in('previewed','erased'),false) is not true or jsonb_typeof(v->'previewErased') is distinct from 'boolean' then return false;end if;
 c:=(v->>'capturedAt')::bigint;e:=(v->>'expiresAt')::bigint;s:=v->>'scope';
